import{_ as t,o as a,c as d,ag as o}from"./chunks/framework.TQKaXlFR.js";const m=JSON.parse('{"title":"参数设置","description":"","frontmatter":{},"headers":[],"relativePath":"features/parameters.md","filePath":"features/parameters.md"}'),s={name:"features/parameters.md"};function i(c,e,r,n,l,h){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="参数设置" tabindex="-1">参数设置 <a class="header-anchor" href="#参数设置" aria-label="Permalink to &quot;参数设置&quot;">​</a></h1><p>入口为 <strong>系统管理 → 参数设置</strong>。这是受控参数目录，不是数据库任意配置编辑器，也不承担业务密钥管理；微信、短信、存储使用<a href="/xinghui-admin-vue3/docs/features/business-config.html">业务配置</a>。</p><h2 id="可管理范围" tabindex="-1">可管理范围 <a class="header-anchor" href="#可管理范围" aria-label="Permalink to &quot;可管理范围&quot;">​</a></h2><p>平台身份及 <code>system:config:*</code> 权限才能管理。服务只暴露目录内的 key，未知历史 key 不作为页面选项。</p><table tabindex="0"><thead><tr><th>key</th><th>合法值/边界</th></tr></thead><tbody><tr><td><code>sys.index.skinName</code></td><td>skin-blue、skin-green、skin-purple、skin-red、skin-yellow</td></tr><tr><td><code>sys.index.sideTheme</code></td><td>theme-dark、theme-light</td></tr><tr><td><code>sys.account.captchaOnOff</code></td><td>true / false；影响验证码有效配置</td></tr><tr><td><code>sys.account.registerUser</code></td><td>true / false；记录不代表已有自助注册能力</td></tr><tr><td><code>sys.index.footerText</code></td><td>可创建的页脚纯文本，最长100字符，不接受HTML/控制字符</td></tr></tbody></table><h2 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h2><p>读取列表，选择已有参数修改 value。新增仅用于允许创建的目录项，不能通过自定义 key 启用一个尚未实现的功能。保存后重新读取，观察 <code>runtimeActive</code> 与 <code>deletable</code>；不是每个存量参数都能删除或立即改变当前浏览器主题。</p><p>接口为 <code>GET /sysConfig/list</code>、<code>GET /sysConfig/{id}</code>、<code>POST /sysConfig</code>、<code>PUT /sysConfig/{id}</code>、<code>DELETE /sysConfig/{id}</code>，保存 body 使用 <code>configKey/configValue</code>。不要套用 <code>/system/config</code> 的假定路径。</p><h2 id="正常结果与恢复" tabindex="-1">正常结果与恢复 <a class="header-anchor" href="#正常结果与恢复" aria-label="Permalink to &quot;正常结果与恢复&quot;">​</a></h2><p>页面展示已保存的 value 和运行状态。验证码相关更新涉及提交后的缓存刷新，应重新打开登录页核对，不用旧页面状态下结论。非法枚举、不可创建 key 或不可删除项会被拒绝；恢复时按目录值重新提交。列表失败可以重试，编辑失败保留内容；不要把供应商密钥填进普通参数 value。</p><h2 id="源码依据" tabindex="-1">源码依据 <a class="header-anchor" href="#源码依据" aria-label="Permalink to &quot;源码依据&quot;">​</a></h2><ul><li>前端：<code>apps/web-ele/src/api/system/config.ts</code>、<code>apps/web-ele/src/views/system/config/index.vue</code>。</li><li>后端：<code>system-admin/src/main/java/com/xinghuiTec/service/impl/SysConfigServiceImpl.java</code> 的 <code>CATALOG</code>、<code>getPublishedValue</code>、有效验证码缓存。</li><li>身份过滤：<code>system-admin/src/main/java/com/xinghuiTec/security/PlatformVisibilityService.java</code>。</li></ul>',12)])])}const f=t(s,[["render",i]]);export{m as __pageData,f as default};
